/* Act III: The Sunless Dawn. Additive events: quest events, the sun_choice finale, and regular events for zones 9-14 plus generic pools.
   Uses only the existing fx vocabulary. Class-gated choices use req.cls for the four new classes. */
Object.assign(G.D.EVENTS, {
  // ================= ZONE 9: THE DROWNED OBSERVATORY =================
  tide_gallery: { zones: [9], ic: 'map', title: 'The Tide Gallery',
    text: 'A long gallery of star charts pinned under glass, half-drowned. The water inside the frames is a different water from the water outside them, and it is moving in the shape of a constellation.',
    choices: [
      { t: 'Dive for the charts', check: { s: 'vit', d: 40 },
        ok: { txt: 'You surface with a fistful of chart-glass, still cold, still faintly lit from within.', fx: z => ({ mats: { starglass: 2 }, xp: 60 * z }) },
        no: { txt: 'The frames close around your arm like tide-pools. You tear free, leaving blood in the water.', fx: { hpPct: -14, dread: 8 } } },
      { t: '[Starseer] Read the moving water', req: { cls: 'starseer' }, out: { txt: 'The water writes the constellation for you in a language the Observatory taught you. It ends on a blank space, and your own name is in it.', fx: z => ({ mats: { starglass: 3 }, xp: 120 * z, dread: 6 }) } },
      { t: 'Wade on', out: { txt: 'The frames watch you leave.', fx: {} } },
    ] },
  mirror_nobody: { zones: [9], ic: 'mirror', title: 'The Mirror That Shows Nothing',
    text: 'A tall astronomer\'s mirror stands upright in the water. It shows the gallery behind you, the lamps, the flooded stairs, every detail in perfect clarity. It does not show you. There is a clean, hooded shape-shaped gap where you should be.',
    choices: [
      { t: 'Study the gap', check: { s: 'wil', d: 45 },
        ok: { txt: 'You hold the empty place in the mirror until it holds you back. A thought arrives, unwelcome and clear: this is what the Keys look like from the outside.', fx: z => ({ codex: 'nomirror', xp: 100 * z, dread: 8 }) },
        no: { txt: 'The gap begins to take a shape. You look away before it finishes. It finishes anyway.', fx: { dread: 16, hpPct: -6 } } },
      { t: '[Veilwalker] Step through the gap', req: { cls: 'veilwalker' }, out: { txt: 'The mirror lets you through as though you were owed. On the far side is a narrow ledge of cold light, and a pouch left there by some earlier walker of veils.', fx: z => ({ item: 2, mats: { voidsilk: 2 }, xp: 90 * z, dread: 6 }) } },
      { t: 'Cover it with your cloak', out: { txt: 'The cloak hangs there a moment, empty, and you are not sure which of you it is covering.', fx: { dread: 4 } } },
    ] },
  lens_room: { zones: [9], ic: 'eye', title: 'The Lens Room',
    text: 'Grinding wheels, polishing cloths, trays of raw glass. Above them all floats an unfinished lens the size of a shield, turning slowly on nothing. Through it the far wall looks a great deal closer than it should.',
    choices: [
      { t: 'Grind a shard from the rim', check: { s: 'int', d: 40 },
        ok: { txt: 'You catch the axis and the glass yields a clean, bright shard. It is warm from its own attention.', fx: { mats: { starglass: 2 }, dread: 4 } },
        no: { txt: 'The lens flinches. A beam of white light crosses the room and takes the skin off your knuckles.', fx: { hpPct: -12, light: -10 } } },
      { t: 'Look through it', check: { s: 'wil', d: 45 },
        ok: { txt: 'The lens shows the sky above the Observatory: a black disc, with a thin gold ring around it, and something moving very slowly in the gap.', fx: z => ({ codex: 'blacknoondread', xp: 110 * z, dread: 10 }) },
        no: { txt: 'The lens shows you looking back. It is a bad angle for both of you.', fx: { dread: 14 } } },
      { t: 'Leave the lens to its turning', out: { txt: 'It does not turn faster. It does not turn slower. You are not sure this is better.', fx: {} } },
    ] },
  brass_tide: { zones: [9], ic: 'gear', title: 'The Brass Tide',
    text: 'The floor of this chamber is a mechanism: interlocking brass rings, half under water, ticking. Clockwork crabs are assembling out of the surf, each one built from the last one\'s spare parts.',
    choices: [
      { t: 'Smash the mechanism', check: { s: 'str', d: 45 },
        ok: { txt: 'You break a ring. The whole floor jolts, and the crabs fall to scrap around your feet.', fx: z => ({ mats: { scrap: 6, starglass: 1 }, xp: 70 * z }) },
        no: { txt: 'The rings bite. The crabs finish assembling in the same moment.', fx: { fight: ['clockworkcrab', 'clockworkcrab'] } } },
      { t: '[Chainwarden] Snarl the gears with your chain', req: { cls: 'chainwarden' }, out: { txt: 'One toss, one wrap, one shriek of stopped brass. The crabs freeze in mid-scuttle. You take what you like from them.', fx: z => ({ mats: { scrap: 8, starglass: 2 }, xp: 100 * z }) } },
      { t: 'Wade around the edge', out: { txt: 'Something small and made of teeth snaps at your ankle and misses.', fx: { hpPct: -4 } } },
    ] },
  astronomer_vigil: { zones: [9], ic: 'moon', title: 'The Astronomer\'s Vigil',
    text: 'A drowned astronomer stands at a tarnished telescope, chest-deep in the flood, counting aloud. The number is not a number you know. Each count, the tide moves a hand\'s breadth higher.',
    choices: [
      { t: 'Count with him', check: { s: 'wil', d: 40 },
        ok: { txt: 'You pick up the count where he drops it. He turns, empty-eyed, and nods, and lets you have the last count. He sinks away with the number, unburdened.', fx: z => ({ dread: -14, xp: 90 * z, cons: { nighttonic: 1 } }) },
        no: { txt: 'You slip a number and the count breaks. The astronomer turns, and the tide with him.', fx: { fight: ['drownedastronomer'], dread: 8 } } },
      { t: 'Offer him a flask of Wick Oil', req: { cons: 'oil' }, out: { txt: 'He pours it on the telescope as if it were a libation. The telescope lights, briefly, and shows him something that makes him weep.', fx: z => ({ cons: { oil: -1 }, xp: 80 * z, dread: -8, mats: { starglass: 1 } }) } },
      { t: 'Interrupt him', out: { txt: 'He does not like to be interrupted. Few of the drowned do.', fx: { fight: ['drownedastronomer', 'lenseye'] } } },
    ] },

  // ================= ZONE 10: THE CINDERWASTE =================
  glass_mannequin: { zones: [10], ic: 'hero', title: 'The Masked Mannequin',
    text: 'A glassblower\'s workshop in the dunes. On a stand in the middle stands a dressmaker\'s mannequin of blown glass, wearing a hood cut exactly like yours. Where the face should be there is only a smooth blank oval, still faintly warm from the furnace.',
    choices: [
      { t: 'Take the hood', check: { s: 'agi', d: 45 },
        ok: { txt: 'It comes away like a shed skin. The lining is good glass-silk; you take it for later.', fx: z => ({ mats: { voidsilk: 2 }, gold: 30 * z, dread: 6 }) },
        no: { txt: 'The mannequin\'s hand closes on your wrist. It lets go slowly, as if reluctant.', fx: { hpPct: -12, dread: 12 } } },
      { t: 'Try the mask on the blank', check: { s: 'wil', d: 50 },
        ok: { txt: 'The blank takes the shape of your hood and gives you back a memory: standing in this workshop, once, holding a hammer that is not in your hands now.', fx: z => ({ codex: 'faceless', xp: 130 * z, dread: 12 }) },
        no: { txt: 'The blank stays blank, and stays looking at you.', fx: { dread: 16 } } },
      { t: '[Veilwalker] Slip the veil over it', req: { cls: 'veilwalker' }, out: { txt: 'Your veil settles over the mannequin like a small ghost. It lifts its head, and for one moment, the two of you agree on something.', fx: { bless: { n: 'Veil-Kinship', stats: { dodge: 10, crit: 5 } }, dread: 4 } },
      },
      { t: 'Leave it', out: { txt: 'You do not look back. You are almost sure it did not turn.', fx: {} } },
    ] },
  dune_forge: { zones: [10], ic: 'anvil', title: 'A Dune Forge',
    text: 'A smith\'s stall half-buried in glass sand: anvil, bellows, quench trough. The coals under the bellows are cold, but the ore in the racks is bright as embers, and it is not cooling.',
    choices: [
      { t: 'Take the ore', out: { txt: 'It burns your palm a little and settles into your pack like a coal in a tin.', fx: { mats: { emberore: 3 }, hpPct: -6 } } },
      { t: '[Sunforger] Light the forge', req: { cls: 'sunforger' }, out: { txt: 'You pump the bellows and strike the first blow on a cold blank. The coals catch. The smith\'s forge remembers a temper, and it teaches yours.', fx: z => ({ mats: { emberore: 4, scrap: 4 }, bless: { n: 'Dune-Temper', stats: { dmg: 10, armor: 8 } }, xp: 100 * z }) } },
      { t: 'Quench a blade in the trough', check: { s: 'int', d: 40 },
        ok: { txt: 'The trough sings. What you draw out is a good, sharp thing, and cold at last.', fx: { item: 2, mats: { emberore: 1 } } },
        no: { txt: 'The water flashes to steam and takes the skin off your arm.', fx: { hpPct: -14 } } },
    ] },
  bright_field: { zones: [10], ic: 'leaf', title: 'The Field of Glass Wheat',
    text: 'A field of wheat fused to glass by a light that touched it once. Every stalk is a tiny sharp lens, and the wind through them makes a sound like a great many small bells. The sunlit lenses throw scattered light across the ground like a net.',
    choices: [
      { t: 'Cross it quickly', check: { s: 'vit', d: 45 },
        ok: { txt: 'The stalks cut through your cloak and skin both, but you cross before the light finds a focus.', fx: z => ({ xp: 80 * z, hpPct: -6 }) },
        no: { txt: 'The scattered light finds a focus on your back.', fx: { hpPct: -18, dread: 6 } } },
      { t: 'Shade your lantern and harvest', check: { s: 'agi', d: 40 },
        ok: { txt: 'You cut a few stalks at the root, keeping your lantern hooded. They shine in your hand like broken stars.', fx: { mats: { starglass: 2 } } },
        no: { txt: 'A stalk flexes and rings, and the whole field starts ringing after it.', fx: { light: -20, dread: 8 } } },
      { t: 'Go around', out: { txt: 'It costs an hour. The hour is fine.', fx: { light: -8 } } },
    ] },
  ash_pilgrims: { zones: [10], ic: 'hero', title: 'Pilgrims of Ash',
    text: 'A line of hooded figures in ash-grey robes shuffles across the dune toward the black sun. Their hoods are empty of anything. Their lanterns are cold. They walk very slowly, as if to a rhythm they cannot hear.',
    choices: [
      { t: 'Walk with them', check: { s: 'wil', d: 45 },
        ok: { txt: 'For a long, quiet mile you are one of them. Then the leader turns, and you both know you cannot go on, and you step out of the line.', fx: z => ({ codex: 'blacknoondread', xp: 110 * z, dread: -6 }) },
        no: { txt: 'You forget why you came. It takes a long time to remember, and the hood that comes with the memory does not fit.', fx: { dread: 18, light: -15 } } },
      { t: 'Offer a Wick Oil', req: { cons: 'oil' }, out: { txt: 'One of them takes the flask and pours it on the ash at its feet. The whole line stops for a moment, as if a small mercy has been done.', fx: z => ({ cons: { oil: -1 }, dread: -12, xp: 70 * z, gold: 30 * z }) } },
      { t: 'Cut them off', out: { txt: 'They stop, all at once. They turn, all at once.', fx: { fight: ['sunscarred', 'sunscarred', 'emberwisp'] } } },
    ] },
  hound_bone: { zones: [10], ic: 'skull', title: 'The Hound\'s Bone-Pile',
    text: 'A great cinderhound sleeps on a mound of bleached bones, ash steaming off its flanks. It is asleep, or making a very good show of it. Beneath the bones something bright winks.',
    choices: [
      { t: 'Creep past it', check: { s: 'agi', d: 45 },
        ok: { txt: 'You lift the bright thing from the pile without a sound. The hound sighs in its sleep and turns over.', fx: z => ({ item: 2, gold: 35 * z }) },
        no: { txt: 'A bone slips. The hound is on its feet before it finishes falling.', fx: { fight: ['cinderhound'] } } },
      { t: 'Lull it with your lantern', check: { s: 'wil', d: 40 },
        ok: { txt: 'It watches the flame for a long moment, then lays its head down. It would like you to sit with it. You do, briefly.', fx: z => ({ xp: 90 * z, dread: -8 }) },
        no: { txt: 'It watches the flame, and it does not like being watched back.', fx: { fight: ['cinderhound', 'cinderhound'] } } },
      { t: 'Back away', out: { txt: 'You take the long way round. The hound opens one eye.', fx: {} } },
    ] },

  // ================= ZONE 11: THE HALL OF NINE LAMPS =================
  forty_wall: { zones: [11], ic: 'lantern', title: 'The Wall of Forty Lanterns',
    text: 'A wall lined floor to ceiling with lanterns, each on its own iron hook, each cold. Beneath each hangs a small brass plate, scratched by hand with a name. The plates are in forty different hands. The last plate, on the last lantern, is blank, and has been polished many times.',
    choices: [
      { t: 'Read the names', check: { s: 'int', d: 45 },
        ok: { txt: 'You read them all. The thirty-ninth is your own, or was, in a hand very like yours. The fortieth is Ivel. The forty-first plate has been waiting for you to arrive.', fx: z => ({ codex: 'fortylanterns', xp: 140 * z, dread: 16 }) },
        no: { txt: 'The names swim together. You read three, and every one of them is yours.', fx: { dread: 14 } } },
      { t: 'Light one', req: { light: 20 }, out: { txt: 'The lantern catches, and burns dim gold. A moment later every lantern on the wall gutters in sympathy, one by one.', fx: z => ({ light: -20, dread: -10, xp: 70 * z, bless: { n: 'Remembered Flame', stats: { resolve: 20 } } }) } },
      { t: '[Chainwarden] Hang your chain on the last hook', req: { cls: 'chainwarden' }, out: { txt: 'The chain settles on the hook with a small, final sound, as if it had always belonged. You feel briefly and terribly at home.', fx: z => ({ bless: { n: 'Warden\'s Post', stats: { armor: 12, resolve: 15 } }, xp: 120 * z, dread: 10 }) } },
      { t: 'Do not look at the plates', out: { txt: 'You walk past with your eyes down. You feel the empty hook looking at your back.', fx: { dread: 6 } } },
    ] },
  ninth_chair: { zones: [11], ic: 'crown', title: 'The Ninth Chair',
    text: 'A round chamber of nine tall chairs around a table of black glass. Eight of them are thick with dust. The ninth is polished, and there is a mug of something still steaming beside it. The mug has been refilled recently.',
    choices: [
      { t: 'Sit in the ninth chair', check: { s: 'wil', d: 50 },
        ok: { txt: 'The chair fits, and you know it. The table shows you a nine-pointed map, and the ninth point is a place you have not been yet.', fx: z => ({ codex: 'ninthflame', xp: 150 * z, dread: 10, reveal: true }) },
        no: { txt: 'The chair does not like your weight. The room rearranges around it.', fx: { fight: ['lampshade', 'lampshade'], dread: 8 } } },
      { t: 'Drink from the mug', out: { txt: 'It tastes like tea, and old lamp-oil, and someone else\'s tiredness. You feel briefly, absurdly, looked after.', fx: { hpPct: 20, dread: -10 } } },
      { t: 'Dust the eighth chair', out: { txt: 'The dust lifts in one long sigh. Something in the room settles, and sets a small brass token by your hand.', fx: z => ({ gold: 40 * z, dread: -4 }) } },
    ] },
  resin_cellar: { zones: [11], ic: 'drop', title: 'The Resin Cellar',
    text: 'Casks of amber lamp-resin line a low cellar, dripping slowly. The air is sweet and close. Every cask is stamped with a small stylised flame, and every one has a tap that has been recently turned.',
    choices: [
      { t: 'Tap a cask', out: { txt: 'The resin comes out thick and slow and smells of every lamp that ever burned. You fill a flask.', fx: { mats: { lampresin: 3 } } } },
      { t: '[Sunforger] Temper a rod in the resin', req: { cls: 'sunforger' }, out: { txt: 'You plunge a red-hot rod into the cask and it comes out black, hard, and quietly humming. The resin remembers being a lamp.', fx: z => ({ mats: { lampresin: 4, emberore: 2 }, bless: { n: 'Resin-Tempered', stats: { armor: 10, hp: 30 } }, xp: 100 * z }) } },
      { t: 'Set a candle to the cask', check: { s: 'agi', d: 45 },
        ok: { txt: 'You light it and step back. It burns slow and gold and very bright, and your lantern drinks from it.', fx: { light: 60, dread: -6 } },
        no: { txt: 'The whole cask catches at once.', fx: { hpPct: -16, light: 20 } } },
    ] },
  sigil_lock: { zones: [11], ic: 'gate', title: 'The Sigil Lock',
    text: 'A door of nine concentric rings, each engraved with a sigil, each with a small dark socket in its centre. It is not the lock that keeps you out. It is the lock that decides whether you are worth the trouble.',
    choices: [
      { t: 'Turn the rings by feel', check: { s: 'int', d: 45 },
        ok: { txt: 'The rings settle, one by one, into a pattern that feels like a name. The door opens on a small strongroom.', fx: z => ({ item: 3, gold: 40 * z }) },
        no: { txt: 'The ninth ring bites. The door does not open, and a warden comes out of the wall to say so.', fx: { fight: ['lampwarden'], hpPct: -6 } } },
      { t: '[Starseer] Read the constellation in the rings', req: { cls: 'starseer' }, out: { txt: 'The nine sigils are a star map with one star missing. You supply it from memory, and the door opens as if pleased to be spoken to correctly.', fx: z => ({ item: 3, mats: { starglass: 2 }, xp: 130 * z }) } },
      { t: 'Force the door', check: { s: 'str', d: 50 },
        ok: { txt: 'The rings scream and the door gives, spilling a cache of old wardens\' supplies.', fx: z => ({ item: 2, gold: 30 * z }) },
        no: { txt: 'The wardens do not appreciate the noise.', fx: { fight: ['lampwarden', 'oathbound'] } } },
    ] },
  dim_procession: { zones: [11], ic: 'wisp', title: 'The Dim Procession',
    text: 'A file of dim flames drifts down the hall, each one carried by nothing, each one leaning slightly toward you. At their head walks a lamp on a pole, held by no hand you can see. They are on their way to the ninth chair.',
    choices: [
      { t: 'Fall in behind them', check: { s: 'wil', d: 45 },
        ok: { txt: 'You walk with the procession to the door of a hall you have not seen. It opens, briefly, on a pool of steady gold, and closes again. You feel rested.', fx: z => ({ dread: -14, xp: 110 * z, focusPct: 60 }) },
        no: { txt: 'One of the flames turns and follows you instead.', fx: { fight: ['dimflame'], dread: 8 } } },
      { t: 'Snuff the last flame', out: { txt: 'It goes out with a small, hurt sound, and the whole file stops and looks at you.', fx: { fight: ['dimflame', 'dimflame'], gold: 60 } } },
      { t: 'Step aside and let them pass', out: { txt: 'They pass. The last one pauses, and leaves a little of its light on your lantern glass before it goes.', fx: { light: 30, dread: -5 } } },
    ] },

  // ================= ZONE 12: THE SUNKEN SUN =================
  own_voice: { zones: [12], ic: 'eye', title: 'In Your Own Voice',
    text: 'Someone speaks from the light ahead of you. It is a kind voice. It is a low voice. It is your voice, with your inflections, saying things you have not said yet. It sounds tired, and it sounds pleased to see you.',
    choices: [
      { t: 'Answer it', check: { s: 'wil', d: 55 },
        ok: { txt: 'You say your own name. The voice pauses, and the pause is a kind of respect. It lets you go with a sentence you will remember: "Come back when you have a face to ask with."', fx: z => ({ codex: 'radiantvoice', xp: 160 * z, dread: 10 }) },
        no: { txt: 'You answer, and the voice agrees with you so warmly that you forget what you said.', fx: { dread: 22, hpPct: -8 } } },
      { t: '[Veilwalker] Speak in someone else\'s voice', req: { cls: 'veilwalker' }, out: { txt: 'You speak in a stranger\'s voice, and the light has no answer for a stranger. It goes quiet, puzzled, and lets you go by.', fx: z => ({ xp: 140 * z, dread: -8 }) } },
      { t: 'Refuse to listen', out: { txt: 'You put your hand over your mouth, which is, you realise later, exactly what your voice was doing.', fx: { dread: 8 } } },
    ] },
  warm_pool: { zones: [12], ic: 'drop', title: 'A Pool of Warm Light',
    text: 'A shallow basin of liquid light glows in a hollow of gold stone. It is not water. It is the memory of a summer afternoon, condensed. Bathing in it would be very nice, and probably a mistake.',
    choices: [
      { t: 'Bathe in it', check: { s: 'vit', d: 50 },
        ok: { txt: 'Every ache lifts. Every old wound, every old regret, warms and lets go. When you step out, you cast a faint shadow of gold.', fx: { hpPct: 50, dread: -20, bless: { n: 'Afterglow', stats: { hp: 40, regen: 3 } } } },
        no: { txt: 'It is too warm. It is much too warm. Some part of you does not want to leave, and the part that does has to drag the rest out.', fx: { hpPct: -20, dread: 14 } } },
      { t: 'Fill a flask', out: { txt: 'The light settles in the glass like a slow small sun. It will keep, for a while.', fx: { cons: { lightflask: 2 } } } },
      { t: 'Refuse the temptation', out: { txt: 'You walk on. The pool does not seem offended. It has all the time in the world.', fx: { dread: -4 } } },
    ] },
  dawn_choir: { zones: [12], ic: 'hero', title: 'The Husks at the Threshold',
    text: 'A circle of dawn husks kneels in the light, all facing the same direction, all with their eyes fused open. They are perfectly still. The light on their faces is the brightest thing you have seen in this world.',
    choices: [
      { t: 'Slip past behind them', check: { s: 'agi', d: 50 },
        ok: { txt: 'You go through the ring like a shadow through a doorway. Not one turns.', fx: z => ({ xp: 100 * z, gold: 30 * z }) },
        no: { txt: 'One turns. Then all of them.', fx: { fight: ['dawnhusk', 'dawnhusk', 'dawnhusk'] } } },
      { t: '[Chainwarden] Bind them together', req: { cls: 'chainwarden' }, out: { txt: 'You loop the chain around the circle and draw it taut. They do not resist. They were waiting to be held. You take what they were carrying.', fx: z => ({ mats: { sunsteel: 1 }, gold: 50 * z, xp: 130 * z }) } },
      { t: 'Strike first', out: { txt: 'They rise as one, and none of them look away from the light while they do it.', fx: { fight: ['dawnhusk', 'dawnhusk', 'brightwraith'], item: 2 } } },
    ] },
  key_rack: { zones: [12], ic: 'treasure', title: 'The Rack of Keys',
    text: 'A rack of forty lantern-shaped keys hangs in the golden light, each on a thin chain, each with a tiny plate. They are cold, except for one at the end, which is warm. The plate under that one is blank.',
    choices: [
      { t: 'Take the warm key', check: { s: 'int', d: 50 },
        ok: { txt: 'It fits into no lock you can see, but it fits your hand exactly. The light under the plate says only: "SOON".', fx: z => ({ item: 3, codex: 'forty', xp: 140 * z, dread: 12 }) },
        no: { txt: 'The key is too warm to hold. It burns a shape into your palm that looks, for a moment, like a name.', fx: { hpPct: -14, dread: 14 } } },
      { t: 'Read the plates', check: { s: 'wil', d: 45 },
        ok: { txt: 'Thirty-nine plates in thirty-nine hands. The fortieth says "IVEL". The forty-first says nothing at all, and is warm.', fx: z => ({ codex: 'forty', xp: 120 * z, dread: 10 }) },
        no: { txt: 'One of the plates has your handwriting on it. You cannot remember writing it.', fx: { dread: 16 } } },
      { t: 'Leave the rack', out: { txt: 'The warm key sways gently as you go, as if to wave.', fx: { dread: 4 } } },
    ] },
  eclipse_edge: { zones: [12], ic: 'moon', title: 'The Eclipse Edge',
    text: 'A place where the light stops. On one side is the lid: cool, blue-black, silent. On the other is the sun: gold, hot, humming. Between them runs a single sharp line across the floor, and you can put a foot on either side.',
    choices: [
      { t: 'Step into the shadow', out: { txt: 'The dark is cool and clean, and it knows your name. It holds you for a while, kindly. Then it lets you go, a little lighter.', fx: { dread: -20, light: -20, focusPct: 40 } } },
      { t: 'Step into the light', check: { s: 'vit', d: 50 },
        ok: { txt: 'The light fills you and does not burn. You take a breath, and the breath is gold.', fx: { hpPct: 40, dread: 10, bless: { n: 'Sunblessed', stats: { dmg: 15, holy: 15 } } } },
        no: { txt: 'The light takes its toll in a single moment. You step back, singed and shaking.', fx: { hpPct: -22, dread: 12 } } },
      { t: '[Starseer] Measure the line', req: { cls: 'starseer' }, out: { txt: 'The edge is not straight. It is a circle, very large, and you are standing on the inside of it. You write the radius on your sleeve for later.', fx: z => ({ mats: { starglass: 2, sunsteel: 1 }, xp: 150 * z, dread: 6 }) } },
    ] },

  // ================= ZONE 13: THE WEEPING MINES =================
  shift_bell: { zones: [13], ic: 'bell', title: 'The Shift Bell',
    text: 'A hand-bell hangs from a rope in a crossing of shafts. Below it, on the timbers, a dozen names are scratched, each with a tally of days beside it, each tally longer than it should be. The bell is still swinging.',
    choices: [
      { t: 'Ring the bell yourself', out: { txt: 'The tolling rolls through the mine. Somewhere a great many picks stop at once.', fx: { fight: ['hollowminer', 'hollowminer'], gold: 100 } } },
      { t: 'Stop the bell', check: { s: 'wil', d: 30 },
        ok: { txt: 'You lay your palm on the bronze. It goes quiet with a tired sigh, and the whole mine loosens a little.', fx: z => ({ dread: -12, xp: 60 * z }) },
        no: { txt: 'The bell resists. It has been ringing so long it has forgotten how not to.', fx: { dread: 10 } } },
      { t: 'Cut the rope and take the bell', check: { s: 'str', d: 25 },
        ok: { txt: 'The bell weighs a good deal, but it is bronze, and Orla will pay for bronze.', fx: z => ({ gold: 30 * z, mats: { scrap: 4 } }) },
        no: { txt: 'The rope frays and the bell crashes down beside you, missing your foot.', fx: { hpPct: -8, fight: ['hollowminer'] } } },
    ] },
  slag_pool: { zones: [13], ic: 'flame', title: 'The Slag Pool',
    text: 'A basin of glowing slag fills the bottom of an old smelting chamber, thick as porridge and bright as sunset. It is not cooling, though the mine has been empty for a hundred years. Bits of ore rise slowly to its surface, like fish.',
    choices: [
      { t: 'Fish out the ore', check: { s: 'agi', d: 30 },
        ok: { txt: 'You snag a piece on a bent pick and pull it, still glowing, to the stone.', fx: { mats: { emberore: 2, scrap: 3 } } },
        no: { txt: 'The slag spits, and the ore sinks.', fx: { hpPct: -10 } } },
      { t: '[Sunforger] Ladle it into a mould', req: { cls: 'sunforger' }, out: { txt: 'You know slag the way other people know their neighbours. You skim, pour and strike, and come away with a small bar of properly good metal.', fx: z => ({ mats: { emberore: 3, scrap: 6 }, xp: 60 * z }) } },
      { t: 'Leave it to cool', out: { txt: 'It will not cool. You leave it to be hot in peace.', fx: {} } },
    ] },
  miner_lamps: { zones: [13], ic: 'lantern', title: 'The Row of Lamps',
    text: 'A rack of miners\' lamps hangs by the shaft mouth, one per hook, one for every miner who ever went down. About half are still lit, burning small and steady and blue.',
    choices: [
      { t: 'Take a lit lamp', check: { s: 'wil', d: 25 },
        ok: { txt: 'The lamp goes quiet in your hand, as if it had been waiting for someone to carry it home.', fx: { light: 45, dread: -6 } },
        no: { txt: 'A hollow miner steps out of the dark, reaching for its lamp.', fx: { fight: ['hollowminer'] } } },
      { t: 'Snuff the lit ones', out: { txt: 'One by one they go out. In the dark behind them, picks that have been swinging for a hundred years finally stop.', fx: z => ({ xp: 60 * z, dread: 4 }) } },
      { t: 'Leave them lit', out: { txt: 'It seems only fair.', fx: { dread: -4 } } },
    ] },
  still_working: { zones: [13], ic: 'hammer', title: 'A Shift Still Working',
    text: 'A crew of hollow miners hacks at a seam in perfect unison, swinging picks that ring like a slow drum. They have been working that seam for a century, and it has yielded nothing but a slightly deeper hollow.',
    choices: [
      { t: 'Sneak past the crew', check: { s: 'agi', d: 30 },
        ok: { txt: 'You pass a swing\'s breadth from the last man\'s pick. The count does not change.', fx: z => ({ xp: 50 * z }) },
        no: { txt: 'Someone misses a beat. The whole crew turns.', fx: { fight: ['hollowminer', 'hollowminer', 'slagworm'] } } },
      { t: '[Chainwarden] Chain the picks', req: { cls: 'chainwarden' }, out: { txt: 'A throw, a snap, a taut ring of iron. The picks stop, and the crew stands very still, as if they had been waiting for someone to take their tools.', fx: z => ({ mats: { emberore: 2 }, gold: 30 * z, xp: 80 * z }) } },
      { t: 'Join the crew for a shift', check: { s: 'str', d: 25 },
        ok: { txt: 'You swing until your arms ache and the crew nods. The seam gives a small, bright seam of ore. They leave it to you, and go back to work.', fx: { mats: { emberore: 2 }, hpPct: -6 } },
        no: { txt: 'You do not have the rhythm. They notice.', fx: { fight: ['hollowminer', 'hollowminer'] } } },
    ] },

  // ================= ZONE 14: THE MOTH WARREN =================
  cocoon_wall: { zones: [14], ic: 'cage', title: 'The Cocoon Wall',
    text: 'A wall of silk cocoons, hundreds of them, each the size of a sleeping person, each slowly rising and falling. A few have been recently cut open, neatly, from the top. Something inside the one nearest you is breathing very softly.',
    choices: [
      { t: 'Cut one open', check: { s: 'agi', d: 40 },
        ok: { txt: 'You slit it with a precise stroke. Inside, wrapped in silk, lies a small store of goods someone hid and never came back for.', fx: z => ({ item: 2, gold: 25 * z, mats: { voidsilk: 1 } }) },
        no: { txt: 'What comes out is not a store of goods.', fx: { fight: ['cocoonhusk', 'cocoonhusk'] } } },
      { t: '[Veilwalker] Slip between the cocoons', req: { cls: 'veilwalker' }, out: { txt: 'You move through the rows like a thought, lifting from each a small good thing and leaving each undisturbed. None wake.', fx: z => ({ item: 2, mats: { voidsilk: 2 }, xp: 70 * z }) } },
      { t: 'Leave them sleeping', out: { txt: 'The breathing keeps time with your footsteps for a while.', fx: {} } },
    ] },
  moth_lullaby: { zones: [14], ic: 'moon', title: 'A Lullaby of Wings',
    text: 'The moths are humming. It is a very low, slow tune, a lullaby in several thousand wingbeats, and it makes your eyelids heavy. Somewhere in the humming there is a word, repeated softly, that sounds like "stay".',
    choices: [
      { t: 'Hum along', check: { s: 'wil', d: 35 },
        ok: { txt: 'You hum the tune the moths are humming, and slightly off it. They part around you, puzzled, and let you through.', fx: z => ({ dread: -12, xp: 70 * z, focusPct: 40 }) },
        no: { txt: 'You hum in tune. The moths are pleased. So pleased.', fx: { dread: 14, light: -20 } } },
      { t: 'Cover your ears and run', out: { txt: 'You run until the word stops. It stops a good deal later than you would like.', fx: { light: -12, dread: 6 } } },
      { t: 'Silence them with fire', out: { txt: 'The flame catches, and the moths scream in unison, and then the whole chamber is alive and angry.', fx: { fight: ['dustmoth', 'dustmoth', 'lampmoth'], gold: 80 } } },
    ] },
  keeper_ledger: { zones: [14], ic: 'scroll', title: 'The Mothkeeper\'s Ledger',
    text: 'A mothkeeper sits at a small writing desk among the silk, entering something in a ledger with a very fine pen. It is masked with a fold of grey gauze. It does not look up. The ledger lists moths, by name, in a beautiful hand.',
    choices: [
      { t: 'Ask what it is writing', check: { s: 'int', d: 35 },
        ok: { txt: 'It shows you a page: a list of every lantern that has come into the Warren, and every flame each one lost to the moths. Your name is on the last line, with a small tally beside it.', fx: z => ({ codex: 'warren', xp: 90 * z, dread: 8 }) },
        no: { txt: 'It does not answer. It turns the page, and the next page is blank except for your name.', fx: { dread: 10 } } },
      { t: 'Trade it a Wick Oil', req: { cons: 'oil' }, out: { txt: 'It accepts the flask with a small, courtly bow, and passes you a roll of silk without a word.', fx: z => ({ cons: { oil: -1 }, mats: { voidsilk: 1 }, gold: 30 * z }) } },
      { t: 'Strike the desk', out: { txt: 'The desk breaks. The keeper rises, and it is much taller than it seemed.', fx: { fight: ['mothkeeper', 'dustmoth'] } } },
    ] },
  gnawed_lantern: { zones: [14], ic: 'lantern', title: 'The Gnawed Lantern',
    text: 'A lantern lies half-buried in silk, its glass eaten through, its brass frame chewed to lace. Whoever carried it was very fond of it. The moths were fonder.',
    choices: [
      { t: 'Salvage what remains', check: { s: 'int', d: 35 },
        ok: { txt: 'The frame is ruined, but the wick-assembly is intact. It fits your own lantern like a glove.', fx: { light: 40, mats: { scrap: 3, shard: 1 } } },
        no: { txt: 'It comes apart in your hands, in a small dry rain of brass.', fx: { mats: { scrap: 1 } } } },
      { t: 'Bury it in silk', out: { txt: 'You cover it gently. A moth lands on the mound, and stays.', fx: z => ({ dread: -8, xp: 50 * z }) } },
      { t: 'Leave it', out: { txt: 'The moths do not thank you.', fx: {} } },
    ] },

  // ================= ZONES 1-3: EARLY ECHOES OF THE BLACK NOON =================
  ghost_apprentice: { zones: [1, 2, 3], ic: 'anvil', title: 'The Ghost Apprentice',
    text: 'A smith\'s apprentice made of soot and old sweat stands at a cold anvil, trying to finish a weld. He has been trying for a hundred years. The seam is very nearly closed. There is a hammer lying at his feet, and he keeps not-quite-reaching for it.',
    choices: [
      { t: 'Hand him the hammer', out: { txt: 'His fingers close on it, and the weld closes with a small bright sound. He looks up, and if he had a face it would be grateful. Then he is smoke.', fx: z => ({ xp: 40 * z, dread: -10, mats: { scrap: 3 } }) } },
      { t: '[Sunforger] Finish the weld', req: { cls: 'sunforger' }, out: { txt: 'You take the hammer and strike the seam once, and it holds. The apprentice bows to a fellow smith, and fades, leaving a good tool behind.', fx: z => ({ item: 2, xp: 60 * z, dread: -8 }) } },
      { t: 'Leave him to it', out: { txt: 'He is very nearly done. He always will be.', fx: {} } },
    ] },
  tin_lantern: { zones: [1, 2, 3], ic: 'lantern', title: 'A Tin Lantern',
    text: 'A dead Lanternbearer sits propped against a wall, hood up, hands folded around a tin lantern that is still lit. The flame is small, steady and very white. It does not seem to need oil.',
    choices: [
      { t: 'Take the lantern', check: { s: 'wil', d: 25 },
        ok: { txt: 'The flame shifts into your own lantern with a small, satisfied flare. The dead hands stay folded.', fx: { light: 45, dread: 6 } },
        no: { txt: 'The dead hands do not let go. You wrench it free, and something wrenches back.', fx: { hpPct: -8, dread: 10 } } },
      { t: 'Leave a candle beside them', req: { light: 10 }, out: { txt: 'You light a stub of candle at their knee. Two flames now, in the dark.', fx: { light: -10, dread: -10 } } },
      { t: 'Move on', out: { txt: 'It is not your lantern. You are not sure it is theirs.', fx: {} } },
    ] },
  hood_pegs: { zones: [1, 2, 3], ic: 'hero', title: 'The Peg of Hoods',
    text: 'A long peg-rail in a forgotten dressing room, hung with hoods: dozens of them, grey, black, brown, all smooth and empty. Each one has a small brass number sewn inside the collar. The first is number one. The last is blank.',
    choices: [
      { t: 'Try one on', check: { s: 'wil', d: 30 },
        ok: { txt: 'It fits. It fits so well that you know you have worn it before, and the knowledge sits in your stomach like a stone.', fx: z => ({ xp: 40 * z, dread: 10, codex: 'lanternbearers' }) },
        no: { txt: 'It does not fit. It does not want to.', fx: { dread: 8 } } },
      { t: 'Take the blank one', out: { txt: 'It is warm. Someone was wearing it a moment ago.', fx: z => ({ dread: 12, gold: 15 * z }) } },
      { t: 'Leave them hanging', out: { txt: 'They sway a little, as though something had just breathed on them.', fx: {} } },
    ] },
  starwatcher_lens: { zones: [1, 2, 3], ic: 'eye', title: 'The Starwatcher\'s Lens',
    text: 'A cracked brass lens lies in a niche, the kind astronomers carry into the field. The crack is a clean line. Through it, the ceiling seems to open on a star that is not there.',
    choices: [
      { t: 'Look through it', check: { s: 'int', d: 30 },
        ok: { txt: 'For an instant, you see a black disc against a dark sky, with a thin gold ring around it. Then the crack closes and the vision goes.', fx: z => ({ xp: 50 * z, codex: 'blacknoondread', dread: 6 }) },
        no: { txt: 'The star is looking at you. You look away.', fx: { dread: 12 } } },
      { t: '[Starseer] Align the crack to the pole', req: { cls: 'starseer' }, out: { txt: 'You turn the lens a hair, and the star resolves. It is not a star. It is the corner of a very large hand. You put the lens away gently.', fx: z => ({ xp: 90 * z, mats: { starglass: 1 }, dread: 6 }) } },
      { t: 'Pocket the lens', out: { txt: 'The brass is good. You can sell it.', fx: z => ({ gold: 20 * z }) } },
    ] },
  chained_corpse: { zones: [1, 2, 3], ic: 'cage', title: 'The Chained Corpse',
    text: 'A dead man is chained to a pillar, wrists and ankles, with links of good blackened iron. The chain is far better than anything the man could have afforded. It has been wound round him with great care, and left unlocked.',
    choices: [
      { t: 'Break the chain', check: { s: 'str', d: 30 },
        ok: { txt: 'The links part with a shriek. The corpse slumps, finally allowed to fall. There is a small purse under it.', fx: z => ({ gold: 20 * z, mats: { scrap: 4 } }) },
        no: { txt: 'The chain bites back, and the corpse opens its eyes.', fx: { fight: 'zone', hpPct: -6 } } },
      { t: '[Chainwarden] Read the knots', req: { cls: 'chainwarden' }, out: { txt: 'It is a warden\'s binding, meant not to hold but to keep quiet. You undo it in the reverse order it was tied, and the corpse settles as though someone had finally taken its watch.', fx: z => ({ item: 2, xp: 60 * z, dread: -6 }) } },
      { t: 'Leave him bound', out: { txt: 'He would probably want you to.', fx: { dread: 4 } } },
    ] },
  veil_peddler: { zones: [1, 2, 3], ic: 'coinbag', title: 'A Peddler of Veils',
    text: 'A hooded peddler sits on a rolled carpet and sells veils: black, grey, dusk-violet, each one thin as breath. "Buy a veil, Lanternbearer. The world looks kinder through one. So do you."',
    choices: [
      { t: 'Buy a veil (40 gold)', req: { gold: 40 }, out: { txt: 'You tie it. The world softens. Edges go quiet. You feel lighter, and slightly further away.', fx: { gold: -40, bless: { n: 'Veiled', stats: { dodge: 6, resolve: 10 } } } },
      },
      { t: '[Veilwalker] Haggle in the old tongue', req: { cls: 'veilwalker' }, out: { txt: 'The peddler stops, and tilts a hood. "Ah. One of ours." The veil that changes hands is a good deal finer than the one you asked for.', fx: { bless: { n: 'Veil of the Trade', stats: { dodge: 10, crit: 6 } }, dread: -6 } } },
      { t: 'Ask where the veils come from', out: { txt: '"They come off people who have stopped needing them," the peddler says, gently. You decide not to ask what that means.', fx: z => ({ xp: 30 * z, dread: 8 }) } },
    ] },
  warm_stone: { zones: [1, 2, 3], ic: 'sparkle', title: 'A Warm Stone',
    text: 'A grey stone sits on a ledge, palm-sized, worn smooth. It is warm to the touch. Not lantern-warm, not fire-warm: sun-warm, the way stone is at the end of a long bright afternoon. You have not felt that in a very long time.',
    choices: [
      { t: 'Hold it', check: { s: 'wil', d: 25 },
        ok: { txt: 'For a moment you stand in a field in high summer with a face you cannot see turned up to a sun you can. Then it is a stone again, and you are crying.', fx: z => ({ dread: -20, xp: 40 * z }) },
        no: { txt: 'It is hot. It burns, then it is cold, then it is a stone.', fx: { hpPct: -6, dread: 6 } } },
      { t: 'Pocket it', out: { txt: 'It stays warm in your pack all day, like a coal that never goes out.', fx: { light: 20, dread: -4 } } },
      { t: 'Leave it on the ledge', out: { txt: 'It is not yours to take. It seems fine.', fx: {} } },
    ] },
  lamplighters_note: { zones: [1, 2, 3], ic: 'scroll', title: 'A Scrap of Vellum',
    text: 'A scrap of vellum is pinned under a fallen candlestick. The hand is small and quick and very tired. It reads: "It is not forever. Tell them it is not forever. Tell them the lid is only a lid." There is no signature.',
    choices: [
      { t: 'Read it again', check: { s: 'int', d: 30 },
        ok: { txt: 'You read it three times. The third time, the words rearrange into a date, four hundred years old. Below it, in another hand: "Still holding."', fx: z => ({ xp: 60 * z, dread: 8 }) },
        no: { txt: 'The words lose their meaning the more you look at them.', fx: { dread: 6 } } },
      { t: 'Pocket it', out: { txt: 'It weighs nothing. It will weigh a great deal, later.', fx: z => ({ xp: 30 * z, dread: 4 }) } },
      { t: 'Leave it pinned', out: { txt: 'It has waited long enough. A little longer will not hurt.', fx: {} } },
    ] },

  // ================= ZONES 4-8: THE SEEPING OF ACT III =================
  black_puddle: { zones: [4, 5, 6, 7, 8], ic: 'mirror', title: 'A Puddle Under a Black Sun',
    text: 'A puddle on the floor, perfectly still, reflecting a disc of black where the ceiling should be. The disc is ringed with a thin line of gold. It is very far away, and you know it is looking directly at you.',
    choices: [
      { t: 'Look at it', check: { s: 'wil', d: 40 },
        ok: { txt: 'You hold the gaze. The gold ring flickers, once, and you have the clear feeling that it blinked first.', fx: z => ({ codex: 'blacknoondread', xp: 60 * z, dread: 6 }) },
        no: { txt: 'It looks back, and for one moment it says something in your own voice.', fx: { dread: 16 } } },
      { t: 'Step in it', out: { txt: 'The puddle is only a puddle. The sky in it goes out.', fx: { dread: -4 } } },
      { t: 'Walk around', out: { txt: 'You give it a wide berth. It gives you one back.', fx: {} } },
    ] },
  cold_ash_forge: { zones: [4, 5, 6, 7, 8], ic: 'anvil', title: 'A Cold Ash Forge',
    text: 'A little roadside forge, its hearth full of pale ash, its anvil cracked across the face. Someone was making something here, in a hurry, and left. Among the ash there are still a few dark, glowing lumps, like the last coals of a very old fire.',
    choices: [
      { t: 'Rake the ash for ore', check: { s: 'agi', d: 30 },
        ok: { txt: 'The ash parts. You find three lumps of proper ember ore, still warm.', fx: { mats: { emberore: 3 } } },
        no: { txt: 'The ash whirls into your eyes and lungs.', fx: { hpPct: -8, light: -10 } } },
      { t: '[Sunforger] Relight the hearth', req: { cls: 'sunforger' }, out: { txt: 'You blow on the ash once, in the way you were taught, and the hearth coughs to life. In its glow the cracked anvil shows a maker\'s mark you almost recognise.', fx: z => ({ mats: { emberore: 4, scrap: 4 }, xp: 80 * z, bless: { n: 'Hearth-Warmth', stats: { hp: 30, dmg: 6 } } }) } },
      { t: 'Move on', out: { txt: 'The ash settles behind you.', fx: {} } },
    ] },
  fallen_lamplighter: { zones: [4, 5, 6, 7, 8], ic: 'hero', title: 'A Fallen Lamplighter',
    text: 'A body in old grey robes lies face-down beside a pillar. It is very old, and very well-preserved, and it is holding a small lamp that is still lit. A ring on one finger carries a sigil: nine points, one of them scratched out.',
    choices: [
      { t: 'Take the ring', check: { s: 'agi', d: 35 },
        ok: { txt: 'The ring slides off, cold. When you look up, the body has turned its head. It watches you go.', fx: { item: 3, dread: 8 } },
        no: { txt: 'The hand tightens. The ring stays. The body does not seem to mind your leaving.', fx: { dread: 10 } } },
      { t: 'Take the lamp', out: { txt: 'The lamp is old, plain and very light. Its flame leans toward your lantern as though it knew it.', fx: { light: 50, dread: 6 } } },
      { t: 'Cover the body', req: { gold: 0 }, out: { txt: 'You lay your cloak over it. The lamp burns a little steadier.', fx: z => ({ dread: -10, xp: 50 * z }) } },
    ] },
  veil_between: { zones: [4, 5, 6, 7, 8], ic: 'moon', title: 'The Veil Between',
    text: 'A curtain of shadow hangs across the passage, thin, moving, faintly cold, with a little gap at one edge. Behind it the corridor seems to continue, but not exactly. It is the same corridor, seen from somewhere just beside itself.',
    choices: [
      { t: '[Veilwalker] Walk the veil', req: { cls: 'veilwalker' }, out: { txt: 'You step sideways into the gap. For an instant you walk in a hall of shadows, where the dead are only cold, and the living are only bright. You emerge with a small treasure and a strong sense that you have been welcomed.', fx: z => ({ item: 3, xp: 140 * z, dread: -8 }) } },
      { t: 'Push through', check: { s: 'wil', d: 40 },
        ok: { txt: 'You go through, shivering, into the same corridor, a little colder than before.', fx: z => ({ xp: 60 * z, dread: 6 }) },
        no: { txt: 'The veil clings to you like wet linen. You come out the other side with fewer memories than you went in with.', fx: { dread: 14, hpPct: -6 } } },
      { t: 'Go around', out: { txt: 'It takes an hour. The veil sways, as though disappointed.', fx: { light: -10 } } },
    ] },
  starglass_scatter: { zones: [4, 5, 6, 7, 8], ic: 'sparkle', title: 'Scattered Starglass',
    text: 'The floor is strewn with small fragments of a shattered lens: bright, sharp, cool, each one showing a different tiny star. Someone dropped a great deal of careful work here, in a great hurry.',
    choices: [
      { t: 'Gather the fragments', check: { s: 'agi', d: 30 },
        ok: { txt: 'You pick the cleanest, one by one, wrapping each in cloth.', fx: { mats: { starglass: 3 } } },
        no: { txt: 'You cut yourself gathering. The fragments do not mind the blood.', fx: { mats: { starglass: 1 }, hpPct: -8 } } },
      { t: '[Starseer] Reassemble the lens', req: { cls: 'starseer' }, out: { txt: 'The pieces know how to fit. You work by feel, and the lens comes together, clean, bright, and very slightly warm. It shows you a star that is not there, and a small path toward it.', fx: z => ({ mats: { starglass: 4 }, xp: 110 * z, reveal: true }) } },
      { t: 'Step around them', out: { txt: 'They crunch a little anyway.', fx: {} } },
    ] },
  chained_door: { zones: [4, 5, 6, 7, 8], ic: 'gate', title: 'The Chained Door',
    text: 'A door bound in chain, links thick as your wrist, wound a dozen times round the frame. The chain is very old and very well-oiled. Behind the door, something is scratching at the wood, patiently, with a single claw.',
    choices: [
      { t: 'Break the chain', check: { s: 'str', d: 45 },
        ok: { txt: 'The links part. The scratching stops. The door swings open on a dry, lightless closet, and a chest that has been waiting for a very long time.', fx: z => ({ item: 3, gold: 30 * z }) },
        no: { txt: 'The chain resists. The scratching resumes, faster.', fx: { hpPct: -10, dread: 8 } } },
      { t: '[Chainwarden] Undo the binding', req: { cls: 'chainwarden' }, out: { txt: 'You unwind the links in the order they were laid, and the door opens with a quiet, courteous click. The thing behind it was only ever asking to be let out to die.', fx: z => ({ item: 3, xp: 100 * z, dread: -6 }) } },
      { t: 'Leave it chained', out: { txt: 'The scratching follows you to the end of the corridor.', fx: { dread: 6 } } },
    ] },
  whisper_lamp: { zones: [4, 5, 6, 7, 8], ic: 'lantern', title: 'A Lamp That Whispers',
    text: 'A little brass lamp on a shelf, unlit, whispering. It says the same three words over and over, in a very small voice. When you lean in, they are: "not a Key... not a Key... not a Key..."',
    choices: [
      { t: 'Lean in and listen', check: { s: 'wil', d: 35 },
        ok: { txt: 'The whisper changes. It says: "They will tell you it is a lock. It is a lid. Do not let them tell you it is a lid." Then it stops, and does not say anything again.', fx: z => ({ xp: 80 * z, dread: 8 }) },
        no: { txt: 'The whisper goes into your ear and stays there, muttering.', fx: { dread: 14 } } },
      { t: 'Silence it', out: { txt: 'You cover the lamp. It stops. You feel, absurdly, that you did something rude.', fx: { dread: -4 } } },
      { t: 'Light it', req: { light: 10 }, out: { txt: 'The wick catches. The whisper becomes a hum, and the hum becomes a very quiet, warm thanks. The lamp burns on, and lends a little of its light.', fx: z => ({ light: 20, dread: -10, xp: 40 * z }) } },
    ] },
  ash_trader: { zones: [4, 5, 6, 7, 8], ic: 'coinbag', title: 'The Ash-Trader',
    text: 'A short hooded trader sits at a folding table under a lantern that gives no light. On the table: neat piles of ember ore, glass, resin and metal, each in a small dish. A hand-lettered sign reads: "FORGE STOCK. NO QUESTIONS. NO REFUNDS."',
    choices: [
      { t: 'Buy ember ore (60 gold)', req: { gold: 60 }, out: { txt: 'The trader weighs it out with a faint air of disapproval and drops it in your palm.', fx: { gold: -60, mats: { emberore: 3 } } } },
      { t: 'Buy starglass (80 gold)', req: { gold: 80 }, out: { txt: 'Bright and cold in a scrap of cloth. You do not ask where it came from.', fx: { gold: -80, mats: { starglass: 2 } } } },
      { t: 'Sell a Wick Oil for lamp resin', req: { cons: 'oil' }, out: { txt: 'The trader sniffs the oil, nods once, and passes you a dish of amber.', fx: { cons: { oil: -1 }, mats: { lampresin: 2 } } } },
      { t: 'Leave', out: { txt: '"No refunds," the trader murmurs, to no one.', fx: {} } },
    ] },

  // ================= ACT III QUEST EVENTS =================
  orrery_chart: { quest: true, ic: 'map', title: 'The Chart Room',
    text: 'A round chamber, its dome a single brass ring. On the wall hangs a star chart drawn on stretched vellum, nine orbits around a black disc. A dozen lenseyes hover in the air below it, silently reading it over and over. The chart\'s corners are pinned with nine small brass lamps.',
    choices: [
      { t: 'Cut the chart from its pins', check: { s: 'agi', d: 45 },
        ok: { txt: 'The chart falls into your hand without a sound. The lenseyes do not look up from where it used to be.', fx: { qitem: 'star_chart', xp: 300, dread: 6 } },
        no: { txt: 'A pin snaps. Twelve lenses turn in the same instant.', fx: { qitem: 'star_chart', fight: ['lenseye', 'lenseye', 'clockworkcrab'] } } },
      { t: '[Starseer] Ask the lenses for it', req: { cls: 'starseer' }, out: { txt: 'You speak the old astronomers\' request for a loan, in the correct cadence. The lenses part and dip, the chart comes down, and you leave with their permission and their suspicion.', fx: { qitem: 'star_chart', xp: 400, codex: 'lid' } } },
      { t: 'Smash the lenses and take it', check: { s: 'str', d: 45 },
        ok: { txt: 'Glass rains. The chart is yours, and the room is quiet.', fx: { qitem: 'star_chart', mats: { starglass: 2 } } },
        no: { txt: 'The lenses hold their own, and hold their grudge.', fx: { qitem: 'star_chart', fight: ['lenseye', 'lenseye', 'lenseye'] } } },
    ] },
  glass_grave: { quest: true, ic: 'sparkle', title: 'The Glass Graves',
    text: 'Coffins of blown glass lie in the dune in neat rows, each with a sleeper still inside, perfectly preserved and faceless in the glare. In the centre lies an empty coffin whose lid has been carefully closed. Through the glass you can see a lens lying inside, ground from something brighter than glass.',
    choices: [
      { t: 'Dig down and open it', check: { s: 'str', d: 45 },
        ok: { txt: 'The lid lifts with a sound like a breath. The lens rests on folded silk, bright as a held ember. It is warm.', fx: { qitem: 'sunglass', xp: 350, dread: 6 } },
        no: { txt: 'The lid cracks. The glass around you begins, softly, to ring.', fx: { qitem: 'sunglass', fight: ['glasswalker', 'glasswalker'] } } },
      { t: '[Sunforger] Soften the glass with heat', req: { cls: 'sunforger' }, out: { txt: 'You bring a spark from your own forge-fire to the lid and it sags, slow as wax, and lets the lens go. You know this trick: glass is only sand that has been asked politely.', fx: { qitem: 'sunglass', xp: 450, mats: { starglass: 1 } } } },
      { t: 'Pray over the sleepers first', check: { s: 'wil', d: 40 },
        ok: { txt: 'You stand a moment in silence. The glass sings once, softly, and the lid opens by itself.', fx: { qitem: 'sunglass', xp: 350, dread: -8 } },
        no: { txt: 'The silence does not last. Several of the sleepers are no longer sleeping.', fx: { qitem: 'sunglass', fight: ['glasswalker', 'glasswalker', 'emberwisp'] } } },
    ] },
  lamp_hall: { quest: true, ic: 'lantern', title: 'The Lamp-Wardens\' Vault',
    text: 'A great circular vault, nine alcoves round its edge, each with a small stone dais and a small socket. In eight of them hangs a sigil on a chain, and the eight lamps above them are cold. Behind the daises, a wall of forty lanterns and forty brass plates has been polished so many times that the letters glow.',
    choices: [
      { t: 'Take the sigils, and look away from the wall', check: { s: 'wil', d: 50 },
        ok: { txt: 'You take them without reading a single plate. You will be glad of it. Later, you will not be sure you are glad.', fx: { qitem: 'nine_sigils', xp: 450, dread: 6 } },
        no: { txt: 'You look. You cannot help it. The wall reads back.', fx: { qitem: 'nine_sigils', codex: 'fortylanterns', dread: 18 } } },
      { t: 'Read the wall first', check: { s: 'int', d: 45 },
        ok: { txt: 'Forty names. Thirty-nine in the order of their failure. The fortieth is Ivel. The forty-first plate is blank, and the lantern under it is unlit, and was made for you. You take the sigils with steady hands and a hollow, quiet, complete understanding.', fx: { qitem: 'nine_sigils', codex: 'fortylanterns', xp: 550, dread: 20 } },
        no: { txt: 'You read three names and then do not read any more. You take the sigils quickly.', fx: { qitem: 'nine_sigils', dread: 14 } } },
      { t: '[Chainwarden] Unhook the sigils by their chains', req: { cls: 'chainwarden' }, out: { txt: 'You know these chains: they are warden-chains, meant to hold a lock, not a lamp. They release to a warden\'s tug. The nine sigils fall into your hand like well-trained hounds.', fx: { qitem: 'nine_sigils', xp: 500, dread: 4 } } },
    ] },
  lamp_hollow: { quest: true, ic: 'lantern', title: 'The Foreman\'s Hook',
    text: 'A dead shaft, black, quiet. On a hook at its end hangs a single miner\'s lamp, burning blue and steady in still air. Slagbrutes stand in the shadows on either side, shoulder to shoulder, so still that they almost look like part of the wall.',
    choices: [
      { t: 'Lift the lamp off its hook', check: { s: 'agi', d: 30 },
        ok: { txt: 'You lift it as if from a sleeping child. The brutes shift, but do not wake.', fx: { qitem: 'foreman_lamp', xp: 150 } },
        no: { txt: 'The hook rings. The brutes do not need a second warning.', fx: { qitem: 'foreman_lamp', fight: ['slagbrute'] } } },
      { t: 'Smash a way through', out: { txt: 'The brutes wake with a sound like iron on iron. The lamp swings on its hook, patient.', fx: { qitem: 'foreman_lamp', fight: ['slagbrute', 'stonechewer'] } } },
      { t: '[Sunforger] Ask the smelters\' way', req: { cls: 'sunforger' }, out: { txt: 'You strike three quiet blows on the nearest anvil, the old smelter\'s salute. The brutes settle, and let you take the lamp.', fx: { qitem: 'foreman_lamp', xp: 250, mats: { emberore: 2 } } } },
    ] },
  silk_loom: { quest: true, ic: 'wisp', title: 'The Warren Loom',
    text: 'A huge wooden loom stands in a chamber of silk, its shuttle moving on its own, its threads faintly luminous. A bolt of pale, weightless cloth is rising on the beam. A mothkeeper stands beside it, tending the shuttle with fine, patient hands.',
    choices: [
      { t: 'Cut a length from the beam', check: { s: 'agi', d: 40 },
        ok: { txt: 'A single stroke and the silk is in your hands, light as breath, strong as chain. The keeper does not turn. The shuttle does not stop.', fx: { qitem: 'moth_silk', xp: 300 } },
        no: { txt: 'The keeper turns, and the loom stops.', fx: { qitem: 'moth_silk', fight: ['mothkeeper', 'dustmoth'] } } },
      { t: '[Veilwalker] Take it from behind the veil', req: { cls: 'veilwalker' }, out: { txt: 'You step out of the keeper\'s notice, and back in, with a bolt of silk in your arms. The loom never misses a stitch.', fx: { qitem: 'moth_silk', xp: 400, mats: { voidsilk: 2 } } } },
      { t: 'Ask the keeper for some', check: { s: 'wil', d: 35 },
        ok: { txt: 'The keeper hesitates, then measures a length by the span of its arms. It bows, very slightly, and returns to the loom.', fx: { qitem: 'moth_silk', xp: 250, dread: -6 } },
        no: { txt: 'The keeper answers in a chorus of wings.', fx: { qitem: 'moth_silk', fight: ['mothkeeper', 'lampmoth'] } } },
    ] },
  log_desk: { quest: true, ic: 'tome', title: 'The Astronomer\'s Desk',
    text: 'A small desk in a small alcove, above the waterline. A brass lamp still burns on it. A leather log lies open beside a dry pen; its pages are full of small cramped handwriting that gets more cramped as it goes. At the last page the handwriting has become a scrawl.',
    choices: [
      { t: 'Take the log', out: { txt: 'The pen rolls off the desk and hits the floor. Somewhere in the flooded corridor, something wakes up.', fx: { qitem: 'astro_log', xp: 200, fight: ['drownedastronomer'] } } },
      { t: 'Read the last page first', check: { s: 'int', d: 40 },
        ok: { txt: 'It reads: "It is not a star. It is watching us watch it. Please stop counting." You close the log gently and take it with you.', fx: { qitem: 'astro_log', xp: 320, dread: 10 } },
        no: { txt: 'The scrawl is illegible, and the illegible parts are worse than the legible ones.', fx: { qitem: 'astro_log', dread: 12 } } },
      { t: '[Starseer] Finish the last entry', req: { cls: 'starseer' }, out: { txt: 'You take the pen and write the last line the astronomer could not: a date, a sign, and the number of the last star. The lamp goes out politely. The log is yours.', fx: { qitem: 'astro_log', xp: 400, dread: -6 } } },
    ] },
  rose_dune: { quest: true, ic: 'leaf', title: 'The Glass Rose',
    text: 'A single dune crowned with a garden: paths, beds, a low wall, all of it fused to glass by one bright afternoon. In the middle, a single rose blooms in perfect clear crystal, its petals throwing small spectra onto the sand. Something shifts among the glass hedges.',
    choices: [
      { t: 'Take the rose', check: { s: 'agi', d: 45 },
        ok: { txt: 'The stem snaps with a small sweet note. The garden holds its breath, and lets you go.', fx: { qitem: 'glass_rose', xp: 350 } },
        no: { txt: 'The stem rings like a struck glass, and every hedge in the garden turns its head.', fx: { qitem: 'glass_rose', fight: ['glasswalker', 'glassgolem'] } } },
      { t: 'Sit with it a while first', check: { s: 'wil', d: 40 },
        ok: { txt: 'You sit among the glass and let the rose throw its colours across you. The garden is quiet. When you rise, the rose leans toward your hand, and comes free.', fx: { qitem: 'glass_rose', xp: 400, dread: -12 } },
        no: { txt: 'You sit too long. Someone else sits beside you.', fx: { qitem: 'glass_rose', dread: 14, fight: ['glasswalker'] } } },
      { t: 'Break the hedge and take it', out: { txt: 'The hedge shatters like a chandelier. Something in the hedge is not glass at all.', fx: { qitem: 'glass_rose', fight: ['glassgolem', 'sunscarred'] } } },
    ] },
  cold_vault: { quest: true, ic: 'treasure', title: 'The Cold Vault',
    text: 'Beneath Kaldrec\'s forge, beyond the last of the fire, lies a door of pale iron rimmed with frost. The frost is unnatural: the cold of it comes from inside. On a hook beside the door hangs a key of the same pale metal, colder than any metal has a right to be.',
    choices: [
      { t: 'Take the key from its hook', check: { s: 'vit', d: 50 },
        ok: { txt: 'It burns cold, then numb. You hold it a long while. It lets you carry it, and asks nothing.', fx: { qitem: 'cold_key', xp: 450, dread: 8 } },
        no: { txt: 'The cold climbs your arm to the shoulder before you drop it, gather it, and go.', fx: { qitem: 'cold_key', hpPct: -18, dread: 10 } } },
      { t: '[Sunforger] Warm it in your hands', req: { cls: 'sunforger' }, out: { txt: 'You hold it against your chest and let your forge-fire warm it, slowly, as a smith warms a cold blank. It comes to your hand like an apology.', fx: { qitem: 'cold_key', xp: 550, dread: -4 } } },
      { t: 'Wrap it and take it', out: { txt: 'You take it in a fold of your cloak. The cloak frosts through.', fx: { qitem: 'cold_key', hpPct: -8, light: -10 } } },
    ] },

  // ================= FINAL: THE SUN CHOICE =================
  sun_choice: { quest: true, ic: 'sparkle', title: 'The Radiant',
    text: 'The Radiant lies open before you, and it is very large, and very tired, and very kind. It has your voice. It uses it gently.\n\n"I was never your enemy," it says. "I was only hungry. They shut me in the dark and taught you to fear the light. I will wake fully and be warm. Or you can put the lid back and be the lock. Or you can take my face, and I will take yours, and there will be a small warm sun in the sky, and it will know your name."\n\nThe forty lanterns hang on the edge of your sight, and one of them, the last, is lit.',
    choices: [
      { t: 'Rekindle the sun', out: { txt: 'You lift your lantern to the open eye and let the glass fall. The Radiant wakes gladly, and day returns, harsh and total.', fx: { end: 'everlight' } } },
      { t: 'Reseal the lid, and become the lock', out: { txt: 'You take the ninth chair and set your lantern in the ninth lamp. The lid settles over the sun like a hand, and the Long Night goes on.', fx: { end: 'longnight' } } },
      { t: 'Wear the sun\'s face', out: { txt: 'You reach up and take the face the Radiant offers. It fits perfectly. It was always meant to fit.', fx: { end: 'sunface' } } },
    ] },
});
